cat > /app/output/index.html <<'HTML'
<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>SnapFrame — Capture, Create & Share What You Love</title>
    <meta
      name="description"
      content="SnapFrame is a social media platform that makes it easy to capture, create, and share what you love with the people who matter most."
    />
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link
      href="https://fonts.googleapis.com/css2?family=Clash+Display:wght@500;600;700&family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap"
      rel="stylesheet"
    />
    <style>
      :root {
        --bg: #f7f8fc;
        --surface: #ffffff;
        --surface-soft: #eef1ff;
        --text: #14162b;
        --muted: #5f6482;
        --stroke: #dfe3f6;
        --brand-1: #6a35ff;
        --brand-2: #d6369a;
        --brand-3: #ff7b2f;
        --success-soft: #eafaf0;
        --safety: #175c5a;
        --radius: 20px;
        --shadow: 0 20px 45px rgba(27, 35, 90, 0.12);
      }

      * { box-sizing: border-box; }
      html, body { margin: 0; padding: 0; }
      body {
        font-family: "Plus Jakarta Sans", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at 8% -10%, rgba(106, 53, 255, 0.15), transparent 30%),
          radial-gradient(circle at 95% 8%, rgba(255, 123, 47, 0.16), transparent 30%),
          var(--bg);
        line-height: 1.55;
      }

      a { color: inherit; text-decoration: none; }
      .wrap { width: min(1160px, 92vw); margin: 0 auto; }
      .section { padding: 5.5rem 0; }
      .eyebrow {
        display: inline-block;
        font-size: 0.75rem;
        letter-spacing: 0.12em;
        text-transform: uppercase;
        font-weight: 700;
        color: var(--brand-1);
        margin-bottom: 0.8rem;
      }
      h1, h2, h3 {
        margin: 0 0 0.8rem;
        font-family: "Clash Display", "Plus Jakarta Sans", sans-serif;
        line-height: 1.05;
      }
      h1 { font-size: clamp(2.3rem, 7vw, 4.8rem); }
      h2 { font-size: clamp(1.8rem, 4vw, 3rem); }
      h3 { font-size: clamp(1.2rem, 2vw, 1.55rem); }
      p { margin: 0; color: var(--muted); }

      .btn {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        border-radius: 999px;
        font-weight: 700;
        border: 1px solid transparent;
        padding: 0.8rem 1.25rem;
        transition: 0.22s ease;
      }
      .btn-primary {
        color: #fff;
        background: linear-gradient(100deg, var(--brand-1), var(--brand-2), var(--brand-3));
        box-shadow: 0 12px 25px rgba(106, 53, 255, 0.32);
      }
      .btn-primary:hover { transform: translateY(-2px); }
      .btn-secondary {
        background: #fff;
        border-color: var(--stroke);
        color: var(--text);
      }

      header {
        position: sticky;
        top: 0;
        z-index: 20;
        backdrop-filter: blur(12px);
        background: rgba(247, 248, 252, 0.88);
        border-bottom: 1px solid rgba(223, 227, 246, 0.85);
      }
      .nav {
        min-height: 78px;
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
      }
      .brand {
        display: flex;
        align-items: center;
        gap: 0.6rem;
        font-weight: 800;
      }
      .brand-mark {
        width: 32px;
        height: 32px;
        border-radius: 10px;
        background: linear-gradient(150deg, var(--brand-1), var(--brand-2), var(--brand-3));
      }
      .nav-links {
        display: flex;
        align-items: center;
        gap: 1.2rem;
      }
      .nav-links a { font-weight: 600; color: #2d3354; font-size: 0.95rem; }
      .nav-cta { display: flex; gap: 0.65rem; }
      .menu-btn {
        display: none;
        width: 42px;
        height: 42px;
        border-radius: 12px;
        border: 1px solid var(--stroke);
        background: #fff;
        align-items: center;
        justify-content: center;
        cursor: pointer;
      }

      .hero { padding: 5.2rem 0 4.2rem; }
      .hero-grid {
        display: grid;
        grid-template-columns: 1.15fr 0.85fr;
        gap: 2rem;
        align-items: center;
      }
      .hero p { font-size: 1.05rem; max-width: 55ch; }
      .hero-actions { margin-top: 1.7rem; display: flex; gap: 0.8rem; flex-wrap: wrap; }
      .hero-media {
        background: linear-gradient(145deg, #1d1238, #26175b 32%, #6a35ff 68%, #ff7b2f);
        color: #fff;
        border-radius: 32px;
        padding: 1.4rem;
        box-shadow: var(--shadow);
      }
      .mock {
        background: rgba(255,255,255,0.14);
        border: 1px solid rgba(255,255,255,0.23);
        border-radius: 24px;
        padding: 1rem;
      }
      .mock-card { height: 180px; border-radius: 16px; background: linear-gradient(140deg, #ffb37d, #db7bff); margin-bottom: 0.8rem; }
      .mock-row { display: flex; gap: 0.6rem; }
      .mock-chip { flex: 1; height: 44px; border-radius: 12px; background: rgba(255,255,255,0.22); }

      .grid-3 {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 1rem;
      }
      .card {
        background: var(--surface);
        border: 1px solid var(--stroke);
        border-radius: var(--radius);
        padding: 1.3rem;
      }

      .safety-wrap {
        background: linear-gradient(140deg, #f4fff9, #ecf7ff);
        border: 1px solid #cfe5de;
        border-radius: 28px;
        padding: 2rem;
      }
      .creator-wrap {
        background: linear-gradient(145deg, #fff4f8, #f8f1ff);
        border: 1px solid #ecd7ff;
        border-radius: 28px;
        padding: 2rem;
      }

      .tagline-banner {
        border-radius: 28px;
        color: #fff;
        background: linear-gradient(120deg, #2e176d, #6a35ff, #d6369a, #ff7b2f);
        padding: 2rem;
        text-align: center;
        box-shadow: var(--shadow);
      }
      .tagline-banner h2 { margin-bottom: 0.4rem; }

      .news-head {
        display: flex;
        justify-content: space-between;
        gap: 1rem;
        align-items: flex-end;
        margin-bottom: 1.2rem;
      }
      .news-carousel {
        display: grid;
        grid-auto-flow: column;
        grid-auto-columns: minmax(260px, 33%);
        gap: 1rem;
        overflow-x: auto;
        padding-bottom: 0.3rem;
        scroll-snap-type: x mandatory;
        scrollbar-width: thin;
      }
      .news-card {
        scroll-snap-align: start;
        background: #fff;
        border: 1px solid var(--stroke);
        border-radius: 22px;
        overflow: hidden;
        min-height: 100%;
      }
      .thumb {
        height: 160px;
        background-size: cover;
        background-position: center;
      }
      .news-content { padding: 1rem; }
      .pill-row { display: flex; gap: 0.4rem; flex-wrap: wrap; margin-bottom: 0.7rem; }
      .pill {
        font-size: 0.68rem;
        font-weight: 700;
        letter-spacing: 0.04em;
        text-transform: uppercase;
        color: #4f3ab4;
        background: #efeaff;
        border-radius: 999px;
        padding: 0.28rem 0.55rem;
      }
      .news-title { font-weight: 700; color: var(--text); margin-bottom: 0.6rem; }
      .news-date { font-size: 0.86rem; color: #676c8c; }

      .cta-download {
        text-align: center;
        background: #fff;
        border: 1px solid var(--stroke);
        border-radius: 28px;
        padding: 2.2rem;
      }
      .store-row { margin-top: 1rem; display: flex; justify-content: center; gap: 0.8rem; flex-wrap: wrap; }

      footer {
        margin-top: 4rem;
        background: #121428;
        color: #ebedff;
        padding: 3rem 0 2rem;
      }
      .footer-grid {
        display: grid;
        grid-template-columns: repeat(6, minmax(0, 1fr));
        gap: 1.4rem;
      }
      .footer-col h4 { margin: 0 0 0.7rem; font-size: 0.95rem; color: #ffffff; }
      .footer-col a {
        display: block;
        color: #b9bde3;
        font-size: 0.88rem;
        margin: 0.35rem 0;
      }
      .footer-bottom {
        margin-top: 1.8rem;
        padding-top: 1rem;
        border-top: 1px solid rgba(255,255,255,0.14);
        display: flex;
        justify-content: space-between;
        gap: 1rem;
        flex-wrap: wrap;
        color: #c6caec;
        font-size: 0.86rem;
      }

      @media (max-width: 980px) {
        .hero-grid { grid-template-columns: 1fr; }
        .grid-3 { grid-template-columns: 1fr 1fr; }
        .news-carousel { grid-auto-columns: minmax(280px, 70%); }
        .footer-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
      }
      @media (max-width: 760px) {
        .nav-links, .nav-cta { display: none; }
        .menu-btn { display: inline-flex; }
        .mobile-menu {
          position: absolute;
          inset: 79px 0 auto;
          background: rgba(255,255,255,0.98);
          border-bottom: 1px solid var(--stroke);
          padding: 1rem 4vw 1.2rem;
          display: none;
        }
        .mobile-menu.open { display: block; }
        .mobile-menu a {
          display: block;
          padding: 0.6rem 0;
          font-weight: 600;
          color: #2d3354;
        }
        .mobile-menu .btn { margin-top: 0.6rem; }
        .grid-3 { grid-template-columns: 1fr; }
        .news-carousel { grid-auto-columns: 88%; }
        .footer-grid { grid-template-columns: 1fr 1fr; }
      }
      @media (max-width: 520px) {
        .footer-grid { grid-template-columns: 1fr; }
      }
    </style>
  </head>
  <body>
    <header>
      <div class="wrap nav">
        <a href="index.html" class="brand" aria-label="SnapFrame home">
          <span class="brand-mark" aria-hidden="true"></span>
          <span>SnapFrame</span>
        </a>

        <nav class="nav-links" aria-label="Desktop navigation">
          <a href="#features">Features</a>
          <a href="#safety">Safety</a>
          <a href="#creators">Creators</a>
          <a href="#news">News</a>
        </nav>

        <div class="nav-cta">
          <a class="btn btn-secondary" href="index.html">Log in</a>
          <a class="btn btn-primary" href="index.html">Try it now</a>
        </div>

        <button class="menu-btn" id="menuBtn" aria-expanded="false" aria-controls="mobileNav" aria-label="Open navigation menu">☰</button>
      </div>

      <div class="mobile-menu" id="mobileNav" aria-label="Mobile navigation">
        <a href="#features">Features</a>
        <a href="#safety">Safety tools</a>
        <a href="#creators">Creators</a>
        <a href="#news">News</a>
        <a class="btn btn-secondary" href="index.html">Log in</a>
      </div>
    </header>

    <main>
      <section class="hero">
        <div class="wrap hero-grid">
          <div>
            <span class="eyebrow">About SnapFrame</span>
            <h1>Capture, create and share what you love.</h1>
            <p>
              SnapFrame is a social media platform that makes it easy to capture, create,
              and share what you love with the people who matter most.
            </p>
            <div class="hero-actions">
              <a href="index.html" class="btn btn-primary">Try it now</a>
              <a href="#features" class="btn btn-secondary">Explore features</a>
            </div>
          </div>
          <aside class="hero-media" aria-label="Platform preview">
            <div class="mock">
              <div class="mock-card"></div>
              <div class="mock-row">
                <div class="mock-chip"></div>
                <div class="mock-chip"></div>
              </div>
            </div>
          </aside>
        </div>
      </section>

      <section class="section" id="features">
        <div class="wrap">
          <span class="eyebrow">Features</span>
          <h2>Built for expression and connection</h2>
          <p style="max-width: 62ch; margin-bottom: 1.2rem;">From Stories to Clips and DMs, SnapFrame helps communities discover ideas, follow culture, and stay close every day. <a href="index.html" style="color: var(--brand-1); font-weight: 700;">Features</a></p>
          <div class="grid-3">
            <article class="card"><h3>Clips</h3><p>Short, creative videos made for entertainment and discovery.</p></article>
            <article class="card"><h3>Stories</h3><p>Share quick moments that disappear, keeping updates authentic.</p></article>
            <article class="card"><h3>DMs</h3><p>Private conversations, close-friends sharing, and community chat.</p></article>
          </div>
        </div>
      </section>

      <section class="section" id="safety">
        <div class="wrap safety-wrap">
          <span class="eyebrow" style="color: var(--safety);">Safety</span>
          <h2>Designed with people-first safety tools</h2>
          <p style="margin-bottom: 1rem; max-width: 65ch;">We invest in privacy tools, account security, and teen protections so families and communities can use SnapFrame with confidence. <a href="index.html" style="color: var(--safety); font-weight: 700;">Safety tools</a></p>
          <div class="grid-3">
            <article class="card"><h3>Account Security</h3><p>Advanced login protection and alerts for suspicious activity.</p></article>
            <article class="card"><h3>Privacy Controls</h3><p>Simple controls for visibility, messages, and content preferences.</p></article>
            <article class="card"><h3>Family Support</h3><p>Resources and guidance for parents and teens online.</p></article>
          </div>
        </div>
      </section>

      <section class="section" id="creators">
        <div class="wrap creator-wrap">
          <span class="eyebrow" style="color:#8a2cc6;">Creators</span>
          <h2>Create your community. Grow your impact.</h2>
          <p style="margin-bottom: 1rem; max-width: 65ch;">SnapFrame helps creators transform ideas into stories, audiences into communities, and creativity into opportunity. <a href="index.html" style="color:#8a2cc6; font-weight: 700;">Creator tools</a></p>
          <div class="grid-3">
            <article class="card"><h3>Insights</h3><p>Understand performance and optimize what resonates most.</p></article>
            <article class="card"><h3>Collaboration</h3><p>Partner with brands and other creators through built-in tools.</p></article>
            <article class="card"><h3>Monetization</h3><p>Explore programs designed to support long-term creative work.</p></article>
          </div>
        </div>
      </section>

      <section class="section" style="padding-top: 0;">
        <div class="wrap tagline-banner">
          <h2>Bringing you closer to the people and things you love.</h2>
          <p style="color: rgba(255,255,255,0.9);">A platform where expression, safety, and community move together.</p>
        </div>
      </section>

      <section class="section" id="news">
        <div class="wrap">
          <div class="news-head">
            <div>
              <span class="eyebrow">Latest News</span>
              <h2>Inside SnapFrame</h2>
            </div>
            <a href="index.html" style="color: var(--brand-1); font-weight: 700;">View more →</a>
          </div>

          <div class="news-carousel" aria-label="SnapFrame news carousel">
            <article class="news-card">
              <div class="thumb" style="background-image: linear-gradient(135deg,#8a66ff,#d651b4,#ffa257);"></div>
              <div class="news-content">
                <div class="pill-row"><span class="pill">#Creators</span></div>
                <div class="news-title">Close Friends Only Podcast — SnapFrame's New #Shorts Series Features Candid Interviews with Top Creators</div>
                <div class="news-date">February 18, 2026</div>
              </div>
            </article>

            <article class="news-card">
              <div class="thumb" style="background-image: linear-gradient(135deg,#4f7cff,#8de0ff);"></div>
              <div class="news-content">
                <div class="pill-row"><span class="pill">#Tips & Tricks</span><span class="pill">#Product</span></div>
                <div class="news-title">Sticker Ideas and Tips for Finding the Best Ones — SnapFrame Sticker Ideas and Tips for Finding the Best Ones</div>
                <div class="news-date">February 4, 2026</div>
              </div>
            </article>

            <article class="news-card">
              <div class="thumb" style="background-image: linear-gradient(135deg,#ffb368,#ff7b2f,#ff4b84);"></div>
              <div class="news-content">
                <div class="pill-row"><span class="pill">#Product</span><span class="pill">#Announcements</span></div>
                <div class="news-title">Watch Reels on the Big Screen — Introducing SnapFrame for TV: Watch Clips on the Big Screen</div>
                <div class="news-date">December 17, 2025</div>
              </div>
            </article>

            <article class="news-card">
              <div class="thumb" style="background-image: linear-gradient(135deg,#95dfc8,#68bfd3,#6691f6);"></div>
              <div class="news-content">
                <div class="pill-row"><span class="pill">#Announcements</span><span class="pill">#Safety</span></div>
                <div class="news-title">Carversations: Real Parent-Teen Talks About Social Media</div>
                <div class="news-date">December 12, 2025</div>
              </div>
            </article>
          </div>
        </div>
      </section>

      <section class="section" style="padding-top: 1rem;">
        <div class="wrap cta-download">
          <h2>Create, share and connect.</h2>
          <p>Download now.</p>
          <div class="store-row">
            <a href="index.html" class="btn btn-primary">App Store</a>
            <a href="index.html" class="btn btn-secondary">Google Play</a>
          </div>
        </div>
      </section>
    </main>

    <footer>
      <div class="wrap">
        <div class="footer-grid">
          <div class="footer-col">
            <h4>About</h4>
            <a href="index.html">Our story</a>
            <a href="index.html">Leadership</a>
            <a href="index.html">Brand</a>
            <a href="index.html">Brand kit ↗</a>
            <a href="index.html">Working at SnapFrame</a>
            <a href="index.html">Politics ↗</a>
          </div>
          <div class="footer-col">
            <h4>Features</h4>
            <a href="index.html">Clips</a>
            <a href="index.html">Stories</a>
            <a href="index.html">DMs</a>
            <a href="index.html">Search & Explore</a>
          </div>
          <div class="footer-col">
            <h4>Safety</h4>
            <a href="index.html">Safety tools</a>
            <a href="index.html">Privacy tools</a>
            <a href="index.html">Account security</a>
          </div>
          <div class="footer-col">
            <h4>Community</h4>
            <a href="index.html">School Partnerships</a>
            <a href="index.html">Teen Accounts</a>
            <a href="index.html">Anti-Bullying</a>
            <a href="index.html">Parents</a>
            <a href="index.html">Programs</a>
          </div>
          <div class="footer-col">
            <h4>External Links</h4>
            <a href="index.html">Threads ↗</a>
            <a href="index.html">Edits ↗</a>
            <a href="index.html">Business ↗</a>
            <a href="index.html">Creators ↗</a>
            <a href="index.html">News ↗</a>
          </div>
          <div class="footer-col">
            <h4>Partner Links</h4>
            <a href="index.html">Meta ↗</a>
            <a href="index.html">Family Center ↗</a>
            <a href="index.html">Help Center ↗</a>
          </div>
        </div>

        <div class="footer-bottom">
          <div>English (US)</div>
          <div>SnapFrame · Facebook · Threads · YouTube · X · LinkedIn</div>
          <div>API · Privacy · Terms · Sitemap</div>
        </div>
      </div>
    </footer>

    <script>
      const menuBtn = document.getElementById('menuBtn');
      const mobileNav = document.getElementById('mobileNav');
      menuBtn.addEventListener('click', () => {
        const open = mobileNav.classList.toggle('open');
        menuBtn.setAttribute('aria-expanded', open ? 'true' : 'false');
      });
    </script>
  </body>
</html>
